>> +
>> +		if (!pskb_may_pull(skb, sizeof(struct iphdr)))
>> +			return false;
>> +
>> +		iph = (struct iphdr *)skb->data;
>> +		if (iph->ihl < 5)
>> +			return false;
>> +
>> +		is_udp = iph->protocol == IPPROTO_UDP;
>> +		l3_hlen = iph->ihl * 4;
>> +	} else if (skb->protocol == htons(ETH_P_IPV6)) {
