--- a/drivers/scsi/aic7xxx/aic7xxx_core.c
+++ b/drivers/scsi/aic7xxx/aic7xxx_core.c
@@ -7064,7 +7064,8 @@ ahc_print_register(const ahc_reg_parse_entry_t *table, u_int num_entries,
 	printed  = printk("%s[0x%x]", name, value);
 	if (table == NULL) {
 		printed += printk(" ");
-		*cur_column += printed;
